import { Inter, Noto_Sans_KR } from "next/font/google";

export const inter = Inter({
  weight: ["400", "500", "600", "700"],
  subsets: ["latin"],
  variable: "--font-inter",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { usePointerParallax } from "./hooks/usePointerParallax";

const TITLE = "POP";
const COMICS = [
  { ko: "풍선이 빵! 하고 터진다.", en: "The bubble goes POP!" },
  { ko: "만화가 짠! 하고 펼쳐진다.", en: "The comic unfurls!" },
  { ko: "색깔이 쨍! 하고 퍼진다.", en: "Color splashes!" },
];

/**
 * POP — 팝, 풍선 만화 가게. Playful-pop entry where bubbles pop on click
 * (spring-press), headlines bounce in (char-split-reveal), and floating
 * shapes drift toward the pointer (pointer-parallax).
 */
export default function PopPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const stageRef = usePointerParallax<HTMLDivElement>(reduced);
  const [popped, setPopped] = useState<number[]>([]);

  useEffect(() => {
    rootRef.current?.classList.add("pop-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "pop" }, "*");
  }, []);

  const togglePop = (i: number) => {
    setPopped((prev) => (prev.includes(i) ? prev.filter((p) => p !== i) : [...prev, i]));
  };

  return (
    <div ref={rootRef} className={`${inter.variable} ${notoSansKR.variable} pop-root`}>
      <div ref={revealRef} className="pop-doc">
        <header className="pop-hero">
          <p className="pop-kicker"><span lang="ko">풍선 만화 가게</span> · BUBBLE COMIC STORE</p>
          <h1 className="pop-title" aria-label="POP 팝">
            {TITLE.split("").map((ch, i) => (
              <span key={i} aria-hidden="true" className="pop-glyph" style={{ "--pop-i": i } as CSSProperties}>{ch}</span>
            ))}
          </h1>
          <p className="pop-title__ko" lang="ko">팝!</p>
          <p className="pop-sub"><span lang="ko">터지는 풍선, 펼쳐지는 만화.</span> Bubbles that pop, comics that unfurl.</p>
        </header>

        {/* spring-press: clickable bubbles that pop */}
        <section ref={stageRef} className="pop-bubbles" data-reveal="">
          <h2 className="pop-secthead"><span lang="ko">터뜨려 보세요</span> · POP THE BUBBLES</h2>
          <div className="pop-bubble-grid">
            {COMICS.map((c, i) => (
              <button
                key={i}
                type="button"
                className={`pop-bubble ${popped.includes(i) ? "is-popped" : ""}`}
                onClick={() => togglePop(i)}
                style={{ "--pop-c": ["#f472b6", "#7dd3fc", "#fde047"][i] } as CSSProperties}
                aria-label={`${c.ko} ${c.en}`}
              >
                <span className="pop-bubble__text" lang="ko">{c.ko}</span>
                <span className="pop-bubble__sfx">{popped.includes(i) ? "빵!" : "POP!"}</span>
              </button>
            ))}
          </div>
          <p className="pop-hint"><span lang="ko">풍선을 누르면 터진다!</span> Click a bubble to pop it!</p>
        </section>

        <footer className="pop-foot" data-reveal="">
          <p>© 2026 POP · <span lang="ko">팝</span> · MIT</p>
          <p><span lang="ko">빵! — 코드로 그렸다.</span> POP! — drawn in code.</p>
        </footer>
      </div>
    </div>
  );
}

/* POP 팝 — bubble comic store · playful-pop
   bubblegum / sky / butter · bubbles that pop with spring physics */

.pop-root {
  --pop-bg: #fff0f6;
  --pop-ink: #1e1b4b;
  --pop-ink-soft: #4c1d95;
  --pop-accent: #f472b6;

  position: relative;
  min-height: 100vh;
  background: var(--pop-bg);
  color: var(--pop-ink);
  font-family: var(--font-inter), var(--font-noto-sans-kr), sans-serif;
  font-weight: 500;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.6;
  overflow-x: hidden;
  overflow-x: clip;
}

.pop-root :lang(ko) { font-family: var(--font-noto-sans-kr), sans-serif; }
.pop-root ::selection { background: var(--pop-accent); color: #fff; }
.pop-root :focus-visible { outline: 3px solid var(--pop-ink); outline-offset: 4px; }

.pop-js [data-reveal] {
  opacity: 0; transform: translateY(24px);
  transition: opacity 800ms cubic-bezier(0.16,1,0.3,1), transform 800ms cubic-bezier(0.16,1,0.3,1);
}
.pop-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .pop-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

.pop-doc { position: relative; z-index: 1; }

/* Hero */
.pop-hero {
  padding: clamp(80px, 16vh, 140px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 60px);
  text-align: center;
}
.pop-kicker {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--pop-accent);
  margin: 0 0 24px;
}
.pop-title {
  font-weight: 900;
  font-size: clamp(5rem, 20vw, 14rem);
  line-height: 0.85;
  margin: 0 0 8px;
  display: flex;
  justify-content: center;
  gap: 0.02em;
  color: var(--pop-ink);
}
/* char-split-reveal: bubbles bounce in with overshoot spring */
.pop-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateY(60px) scale(0.3);
}
.pop-js .pop-glyph {
  animation: pop-bounce 700ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
  animation-delay: calc(var(--pop-i, 0) * 120ms + 200ms);
}
@keyframes pop-bounce { to { opacity: 1; transform: translateY(0) scale(1); } }
@media (prefers-reduced-motion: reduce) {
  .pop-glyph { opacity: 1; transform: none; animation: none; }
}
.pop-title__ko {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 900;
  color: var(--pop-accent);
  margin: 0 0 16px;
}
.pop-sub { color: var(--pop-ink-soft); margin: 0; font-weight: 500; }

/* Bubbles section — pointer-parallax + spring-press */
.pop-bubbles {
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
  transition: transform 500ms cubic-bezier(0.16,1,0.3,1);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .pop-bubbles { transform: none !important; transition: none; }
}
.pop-secthead {
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--pop-accent);
  margin: 0 0 40px;
}
.pop-bubble-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 24px;
}
/* spring-press: bubble buttons with spring animation */
.pop-bubble {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  border: 4px solid var(--pop-ink);
  background: var(--pop-c, var(--pop-accent));
  cursor: pointer;
  font-family: inherit;
  font-weight: 700;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px;
  box-shadow: 6px 6px 0 var(--pop-ink);
  transition: transform 200ms cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 200ms;
}
.pop-bubble:hover { transform: scale(1.05); }
.pop-bubble:active {
  transform: scale(0.88);
  box-shadow: 2px 2px 0 var(--pop-ink);
}
.pop-bubble.is-popped {
  transform: scale(0.7) rotate(-5deg);
  opacity: 0.5;
  box-shadow: none;
}
.pop-bubble__text {
  font-size: 0.85rem;
  color: var(--pop-ink);
  text-align: center;
  line-height: 1.3;
}
.pop-bubble__sfx {
  font-size: 1.2rem;
  font-weight: 900;
  color: var(--pop-ink);
}
.pop-hint {
  margin-top: 32px;
  color: var(--pop-ink-soft);
  font-size: 0.9rem;
}

/* Footer */
.pop-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  border-top: 3px solid var(--pop-ink);
  color: var(--pop-ink-soft);
  font-size: 0.82rem;
  font-weight: 700;
}
.pop-foot p { margin: 0 0 6px; }
